// AI-personalized pricing per visitor
// Novel feature: dynamically adjust price based on visitor behavior, session, and market signals

const express = require('express');
const router = express.Router();

// In-memory store for visitor profiles (replace with DB in production)
const visitorProfiles = new Map();

// Configuration
const BASE_PRICE = 100; // base price in cents
const MAX_DISCOUNT = 0.3; // max 30% discount
const MAX_SURCHARGE = 0.2; // max 20% surcharge

// Helper: compute personalized price
function computePrice(profile) {
  let factor = 1.0;
  // Factor based on session count (loyalty discount)
  if (profile.sessionCount > 5) factor -= 0.05;
  if (profile.sessionCount > 20) factor -= 0.1;
  // Factor based on time on site (engagement)
  if (profile.timeOnSite > 120) factor -= 0.02;
  // Factor based on cart abandonment (recovery)
  if (profile.cartAbandoned) factor -= 0.1;
  // Factor based on referral source (premium for direct)
  if (profile.referrer === 'direct') factor += 0.05;
  // Clamp factor
  factor = Math.max(1 - MAX_DISCOUNT, Math.min(1 + MAX_SURCHARGE, factor));
  return Math.round(BASE_PRICE * factor);
}

// POST /api/personalized-pricing
router.post('/', (req, res) => {
  const { visitorId, sessionCount, timeOnSite, cartAbandoned, referrer } = req.body;
  if (!visitorId) return res.status(400).json({ error: 'visitorId required' });

  // Update or create profile
  let profile = visitorProfiles.get(visitorId) || { sessionCount: 0, timeOnSite: 0, cartAbandoned: false, referrer: 'unknown' };
  profile.sessionCount = sessionCount || profile.sessionCount + 1;
  profile.timeOnSite = timeOnSite || profile.timeOnSite;
  profile.cartAbandoned = cartAbandoned !== undefined ? cartAbandoned : profile.cartAbandoned;
  profile.referrer = referrer || profile.referrer;
  visitorProfiles.set(visitorId, profile);

  const price = computePrice(profile);
  res.json({ visitorId, price, currency: 'USD', factor: price / BASE_PRICE });
});

// GET /api/personalized-pricing/:visitorId
router.get('/:visitorId', (req, res) => {
  const profile = visitorProfiles.get(req.params.visitorId);
  if (!profile) return res.status(404).json({ error: 'visitor not found' });
  const price = computePrice(profile);
  res.json({ visitorId: req.params.visitorId, price, currency: 'USD', factor: price / BASE_PRICE });
});

module.exports = router;
